const setInstanceStarting = `-- name: SetInstanceStarting :execrows
UPDATE instances
SET status = 'starting', generation = $1, uses_exchange = $2, resolved_expires_at = $3, health_check = $4, updated_at = now()
WHERE id = $5 AND status = 'pending'
`

type SetInstanceStartingParams struct {
	Generation        int64
	UsesExchange      bool
	ResolvedExpiresAt pgtype.Timestamptz
	HealthCheck       []byte
	ID                string
}

// Records the generation the objects were rendered and applied with, and the
// earliest expiresAt of the resolver values the render used (null for none). Also records the rendered
// health check the instance keeps (null without one), and whether the
// rendered generation uses an exchanged token.
func (q *Queries) SetInstanceStarting(ctx context.Context, arg SetInstanceStartingParams) (int64, error) {
	result, err := q.db.Exec(ctx, setInstanceStarting,
		arg.Generation,
		arg.UsesExchange,
		arg.ResolvedExpiresAt,
		arg.HealthCheck,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setInstanceStopped = `-- name: SetInstanceStopped :execrows
WITH stopped AS (
    UPDATE instances
    SET status = 'stopped', updated_at = now()
    WHERE instances.id = $1 AND status = 'stopping'
    RETURNING instances.id
), released AS (
    UPDATE persistent_volumes SET instance_id = NULL, last_used_at = now()
    WHERE instance_id IN (SELECT stopped.id FROM stopped)
)
SELECT 1 FROM stopped
`

// Also releases the volumes the instance held, in the same statement, so a
// stopped instance never holds one, whatever the feature setting.
func (q *Queries) SetInstanceStopped(ctx context.Context, id string) (int64, error) {
	result, err := q.db.Exec(ctx, setInstanceStopped, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

